@startuml

class Department {}

class Room {
  + numberOfBeds : int
}

class Bed {
  + category : StayType
}

class StayType {
  + price : float
}

enum StayType {
  RH
  RNH
  SF
}

class Inhabitant {
  + basicIdentificationData : string
}

class Stay {
  + startDate : date
  + endDate : date
  + isSuspended : boolean
  + isInvalidated : boolean
  + isPaid : boolean
  + outstandingAmount : float
}

class Registration {
  + registrationDate : date
  + basicData : string
}

class Assessment {
  + assessmentDate : date
  + needs : string
  + validatedType : StayType
}

class WaitingList {
  + position : int
}

class Proposal {
  + proposalDate : date
  + accepted : boolean
  + refused : boolean
  + isValidated : boolean
}

class Invoice {
  + billingDate : date
  + amount : float
  + outstandingAmount : float
  + isPaid : boolean
  + modify() : void
}

class CreditNote {
  + amount : float
  + executionDate : date
}

Department "1" *-- "*" Room
Room "1" *-- "*" Bed
Bed "1" -- "1" StayType
Inhabitant "1" -- "*" Stay
Stay "*" -- "1" StayType
Inhabitant "1" -- "0..*" Registration
Registration "1" -- "0..1" Assessment
Assessment "1" -- "0..1" WaitingList
WaitingList "1" -- "1" StayType
WaitingList "1" -- "0..*" Proposal
Proposal "0..1" -- "1" Inhabitant
Proposal "0..1" -- "1" StayType
Stay "1" -- "*" Invoice
Invoice "1" -- "0..1" CreditNote
Inhabitant "1" -- "*" Invoice

@enduml

